def solve(g):
    H,W=len(g),len(g[0])
    sr=[i for i,r in enumerate(g) if len(set(r))==1]
    sc=[j for j in range(W) if all(g[i][j]==g[0][j] and g[0][j]!=0 for i in range(H))]
    def bands(seps,N):
        out=[];cur=0
        for s in list(seps)+[N]:
            if s-cur>1: out.append((cur,s-1)); cur=s+1
        return out
    rb=bands(sr,H); cb=bands(sc,W)
    sepcolor=g[sr[0]][0]
    seen=set(); best=None
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 or (i,j) in seen: continue
            v=g[i][j]; stack=[(i,j)]; comp=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen: continue
                seen.add((y,x)); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==v: stack.append((ny,nx))
            rs=[y for y,x in comp];cs=[x for y,x in comp]
            h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
            fill=all(g[y][x]==v for y in range(min(rs),max(rs)+1) for x in range(min(cs),max(cs)+1))
            cand=(len(comp) if not(fill and h==2 and w==2) else -1)
            if best is None or cand>best[0]: best=(cand,comp)
    tpl=best[1]
    th=max(y for y,x in tpl)-min(y for y,x in tpl)+1
    tw=max(x for y,x in tpl)-min(x for y,x in tpl)+1
    r0=min(y for y,x in tpl); c0=min(x for y,x in tpl)
    rel=[(y-r0,x-c0) for y,x in tpl]
    res=[row[:] for row in g]
    def sqc(rr0,rr1,cc0,cc1):
        for cy in range(rr0,rr1-1):
            for cx in range(cc0,cc1-1):
                if g[cy][cx]!=0 and g[cy][cx]==g[cy][cx+1]==g[cy+1][cx]==g[cy+1][cx+1] and all(p not in {k for k,v in []} for p in [(cy,cx),(cy,cx+1),(cy+1,cx),(cy+1,cx+1)]):
                    return g[cy][cx]
        return None
    bcol={bi:sqc(*rb[bi],*cb[0]) for bi in range(len(rb))}
    for bi,(rr0,rr1) in enumerate(rb):
        for bj,(cc0,cc1) in enumerate(cb):
            col=bcol.get(bi)
            if col is None: continue
            rh=rr1-th+1; rw=cc1-tw+1
            for dy,dx in rel:
                y,x=rh+dy, rw+dx
                if 0<=y<H and 0<=x<W: res[y][x]=col
