def solve(g):
    H,W=len(g),len(g[0])
    sr=[i for i,r in enumerate(g) if len(set(r))==1]
    sc=[j for j in range(W) if len(set(g[i][j] for i in range(H)))==1]
    sep=set(sr)|set(sc); sepc=g[sr[0]][0]
    def bands(seps,N):
        out=[];cur=0
        for s in list(seps)+[N]:
            if s-cur>1: out.append((cur,s-1))
            cur=s+1
        return out
    rb=bands(sr,H); cb=bands(sc,W)
    seen=set();comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 or (i,j) in sep: continue
            v=g[i][j]; stack=[(i,j)]; cs={(i,j)}
            while stack:
                y,x=stack.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in cs and g[ny][nx]==v:
                        cs.add((ny,nx)); stack.append((ny,nx))
            seen|=cs; comps.append(cs)
    tmpl=max(comps,key=lambda c:(max(y for y,_ in c)-min(y for y,_ in c)+1)*(max(x for _,x in c)-min(x for _,x in c)+1))
    ty0=min(y for y,_ in tmpl); tx0=min(x for _,x in tmpl)
    th=max(y for y,_ in tmpl)-ty0+1; tw=max(x for _,x in tmpl)-tx0+1
    rel=[(y-ty0,x-tx0) for y,x in tmpl]
    res=[row[:] for row in g]
    for rr0,rr1 in rb:
        mcolors={}
        for i in range(rr0,rr1+1):
            for j in range(W):
                if j in sep or g[i][j]==sepc: continue
                mcolors[g[i][j]]=mcolors.get(g[i][j],0)+1
        col=max(mcolors,key=mcolors.get)
        for cc0,cc1 in cb:
            ay=rr1-th+1; ax=cc0
            for dy,dx in rel:
                y,x=ay+dy,ax+dx
                if 0<=y<H and 0<=x<W and (y,x) not in sep:
                    res[y][x]=col
    return res
