def solve3(g):
    H,W=len(g),len(g[0])
    sr=[i for i in range(H) if len(set(g[i]))==1]
    sc=[j for j in range(W) if len({g[i][j] for i in range(H)})==1]
    sepc=g[sr[0]][0]
    def bands(seps,N):
        out=[];cur=0
        for s in list(seps)+[N]:
            if s-cur>1: out.append((cur,s-1))
            cur=s+1
        return out
    rb=bands(sr,H); cb=bands(sc,W)
    sepset=set(sr)|set(sc)
    # components over non-sep nonzero cells, global
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 or (i,j) in sepset: continue
            v=g[i][j]; st=[(i,j)]; cs={(i,j)}
            while st:
                y,x=st.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in cs and g[ny][nx]==v:
                        cs.add((ny,nx));st.append((ny,nx))
            comps.append((v,cs))
    tv,tpl=max(comps,key=lambda t:len(t[1]))
    R0,R1=min(r for r,c in tpl),max(r for r,c in tpl)
    C0,C1=min(c for r,c in tpl),max(c for r,c in tpl)
    mask={(r-R0,c-C0) for r,c in tpl}
    h,w=R1-R0+1,C1-C0+1
    res=[row[:] for row in g]
    for bi,(r0,r1) in enumerate(rb):
        cnt=Counter(g[r][c] for r in range(r0,r1+1) for c in range(W) if (r,c) not in sepset and g[r][c]!=0)
        others={k:v for k,v in cnt.items() if k!=tv}
        mc=others.most_common(1)[0][0] if others else None
        for bj,(c0,c1) in enumerate(cb):
            ay=r1; ax=c0   # flush bottom-left; bbox is h x w, fits since band height = 4 >= h usually
            if ay+h>H: ay=H-h
            for dr in range(h):
                for dc in range(w):
                    if (dr,dc) in mask:
                        rr,cc=ay+dr,ax+dc
                        if 0<=rr<H and 0<=cc<W:
                            res[rr][cc]=mc
    return res
