def solve(g):
    H,W=len(g),len(g[0])
    sr=[i for i in range(H) if len(set(g[i]))==1]
    sc=[j for j in range(W) if len({g[i][j] for i in range(H)})==1]
    sepc=g[sr[0]][0]
    sepset={(i,j) for i in sr for j in range(W)}|{(i,j) for j in sc for i in range(H)}
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 or (i,j) in sepset: continue
            st=deque([(i,j)]);cs={(i,j)}
            while st:
                y,x=st.popleft()
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if (dy or dx) and 0<=ny<H and 0<=nx<W and (ny,nx) not in cs and g[ny][nx]==g[i][j]:
                            cs.add((ny,nx));st.append((ny,nx))
            comps.append(cs)
    tmpl=max(comps,key=len)
    R0=min(r for r,_ in tmpl);C0=min(c for _,c in tmpl)
    h=max(r for r,_ in tmpl)-R0+1; w=max(c for _,c in tmpl)-C0+1
    mask=frozenset((r-R0,c-C0) for r,c in tmpl)
    res=[row[:] for row in g]
    for r0,r1 in bands(sr,H):
        marks=Counter()
        for r in range(r0,r1+1):
            for c in range(W):
                if (r,c) not in sepset and g[r][c]!=0 and g[r][c]!=(g[R0][min(cc for _,cc in tmpl)]):
                    marks[g[r][c]]+=1
        mc=marks.most_common(1)[0][0] if marks else None
        if mc is None: continue
        for c0,c1 in bands(sc,W):
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if (r,c) not in sepset: res[r][c]=0
            ay=r1-h+1; ax=c0
            for dr,dc in mask:
                rr,cc=ay+dr,ax+dc
                if 0<=rr<H and 0<=cc<W and (rr,cc) not in sepset:
                    res[rr][cc]=mc
    return res

